def target_size_center_crop(self, im, new_hw):
    width, height = im.size
    if width != height:
        im = self.crop(im, min(height, width), min(height, width))
    return im.resize((new_hw, new_hw), PIL.Image.LANCZOS)

def target_size_center_crop(self, im, new_hw):
    """
    Crop and resize the image to the target size while keeping the center.
    """
    width, height = im.size
    if width != height:
        im = self.crop(im, min(height, width), min(height, width))
    return im.resize((new_hw, new_hw), PIL.Image.LANCZOS)

def _default_height_width(self, height, width, image):
    # NOTE: It is possible that a list of images have different
    # dimensions for each image, so just checking the first image
    # is not _exactly_ correct, but it is simple.
    while isinstance(image, list):
        image = image[0]

    if height is None:
        if isinstance(image, PIL.Image.Image):
            height = image.height
        elif isinstance(image, torch.Tensor):
            height = image.shape[-2]

        # round down to nearest multiple of `self.adapter.total_downscale_factor`
        height = (height // self.adapter.total_downscale_factor) * self.adapter.total_downscale_factor

    if width is None:
        if isinstance(image, PIL.Image.Image):
            width = image.width
        elif isinstance(image, torch.Tensor):
            width = image.shape[-1]

        # round down to nearest multiple of `self.adapter.total_downscale_factor`
        width = (width // self.adapter.total_downscale_factor) * self.adapter.total_downscale_factor

    return height, width

