def load_model_dict_into_meta(model, state_dict, device=None, dtype=None, model_name_or_path=None):
    device = device or torch.device("cpu")
    dtype = dtype or torch.float32

    unexpected_keys = []
    empty_state_dict = model.state_dict()
    for param_name, param in state_dict.items():
        if param_name not in empty_state_dict:
            unexpected_keys.append(param_name)
            continue

        if empty_state_dict[param_name].shape != param.shape:
            model_name_or_path_str = f"{model_name_or_path} " if model_name_or_path is not None else ""
            raise ValueError(
                f"Cannot load {model_name_or_path_str}because {param_name} expected shape {empty_state_dict[param_name]}, but got {param.shape}. If you want to instead overwrite randomly initialized weights, please make sure to pass both `low_cpu_mem_usage=False` and `ignore_mismatched_sizes=True`. For more information, see also: https://github.com/huggingface/diffusers/issues/1619#issuecomment-1345604389 as an example."
            )

        accepts_dtype = "dtype" in set(inspect.signature(set_module_tensor_to_device).parameters.keys())
        if accepts_dtype:
            set_module_tensor_to_device(model, param_name, device, value=param, dtype=dtype)
        else:
            set_module_tensor_to_device(model, param_name, device, value=param)
    return unexpected_keys

def convert_state_dict_legacy_attn_format(self, state_dict, network_alphas):
    is_new_lora_format = all(
        key.startswith(self.unet_name) or key.startswith(self.text_encoder_name) for key in state_dict.keys()
    )
    if is_new_lora_format:
        # Strip the `"unet"` prefix.
        is_text_encoder_present = any(key.startswith(self.text_encoder_name) for key in state_dict.keys())
        if is_text_encoder_present:
            warn_message = "The state_dict contains LoRA params corresponding to the text encoder which are not being used here. To use both UNet and text encoder related LoRA params, use [`pipe.load_lora_weights()`](https://huggingface.co/docs/diffusers/main/en/api/loaders#diffusers.loaders.LoraLoaderMixin.load_lora_weights)."
            logger.warn(warn_message)
        unet_keys = [k for k in state_dict.keys() if k.startswith(self.unet_name)]
        state_dict = {k.replace(f"{self.unet_name}.", ""): v for k, v in state_dict.items() if k in unet_keys}

    # change processor format to 'pure' LoRACompatibleLinear format
    if any("processor" in k.split(".") for k in state_dict.keys()):

        def format_to_lora_compatible(key):
            if "processor" not in key.split("."):
                return key
            return key.replace(".processor", "").replace("to_out_lora", "to_out.0.lora").replace("_lora", ".lora")

        state_dict = {format_to_lora_compatible(k): v for k, v in state_dict.items()}

        if network_alphas is not None:
            network_alphas = {format_to_lora_compatible(k): v for k, v in network_alphas.items()}
    return state_dict, network_alphas

def format_to_lora_compatible(key):
    if "processor" not in key.split("."):
        return key
    return key.replace(".processor", "").replace("to_out_lora", "to_out.0.lora").replace("_lora", ".lora")

def __init__(self, dim_in: int, dim_out: int):
    super().__init__()
    self.proj = LoRACompatibleLinear(dim_in, dim_out * 2)

def enable_model_cpu_offload(self, gpu_id: int = 0, device: Union[torch.device, str] = "cuda"):
    r"""
    Offloads all models to CPU using accelerate, reducing memory usage with a low impact on performance. Compared
    to `enable_sequential_cpu_offload`, this method moves one whole model at a time to the GPU when its `forward`
    method is called, and the model remains in GPU until the next model runs. Memory savings are lower than with
    `enable_sequential_cpu_offload`, but performance is much better due to the iterative execution of the `unet`.
    """
    if self.model_cpu_offload_seq is None:
        raise ValueError(
            "Model CPU offload cannot be enabled because no `model_cpu_offload_seq` class attribute is set."
        )

    if is_accelerate_available() and is_accelerate_version(">=", "0.17.0.dev0"):
        from accelerate import cpu_offload_with_hook
    else:
        raise ImportError("`enable_model_cpu_offload` requires `accelerate v0.17.0` or higher.")

    device = torch.device(f"cuda:{gpu_id}")

    if self.device.type != "cpu":
        self.to("cpu", silence_dtype_warnings=True)
        device_mod = getattr(torch, self.device.type, None)
        if hasattr(device_mod, "empty_cache") and device_mod.is_available():
            device_mod.empty_cache()  # otherwise we don't see the memory savings (but they probably exist)

    all_model_components = {k: v for k, v in self.components.items() if isinstance(v, torch.nn.Module)}

    self._all_hooks = []
    hook = None
    for model_str in self.model_cpu_offload_seq.split("->"):
        model = all_model_components.pop(model_str, None)
        if not isinstance(model, torch.nn.Module):
            continue

        _, hook = cpu_offload_with_hook(model, device, prev_module_hook=hook)
        self._all_hooks.append(hook)

    # CPU offload models that are not in the seq chain unless they are explicitly excluded
    # these models will stay on CPU until maybe_free_model_hooks is called
    # some models cannot be in the seq chain because they are iteratively called, such as controlnet
    for name, model in all_model_components.items():
        if not isinstance(model, torch.nn.Module):
            continue

        if name in self._exclude_from_cpu_offload:
            model.to(device)
        else:
            _, hook = cpu_offload_with_hook(model, device)
            self._all_hooks.append(hook)

def enable_sequential_cpu_offload(self, gpu_id: int = 0, device: Union[torch.device, str] = "cuda"):
    r"""
    Offloads all models to CPU using 🤗 Accelerate, significantly reducing memory usage. When called, the state
    dicts of all `torch.nn.Module` components (except those in `self._exclude_from_cpu_offload`) are saved to CPU
    and then moved to `torch.device('meta')` and loaded to GPU only when their specific submodule has its `forward`
    method called. Offloading happens on a submodule basis. Memory savings are higher than with
    `enable_model_cpu_offload`, but performance is lower.
    """
    if is_accelerate_available() and is_accelerate_version(">=", "0.14.0"):
        from accelerate import cpu_offload
    else:
        raise ImportError("`enable_sequential_cpu_offload` requires `accelerate v0.14.0` or higher")

    if device == "cuda":
        device = torch.device(f"{device}:{gpu_id}")

    if self.device.type != "cpu":
        self.to("cpu", silence_dtype_warnings=True)
        device_mod = getattr(torch, self.device.type, None)
        if hasattr(device_mod, "empty_cache") and device_mod.is_available():
            device_mod.empty_cache()  # otherwise we don't see the memory savings (but they probably exist)

    for name, model in self.components.items():
        if not isinstance(model, torch.nn.Module):
            continue

        if name in self._exclude_from_cpu_offload:
            model.to(device)
        else:
            # make sure to offload buffers if not all high level weights
            # are of type nn.Module
            offload_buffers = len(model._parameters) > 0
            cpu_offload(model, device, offload_buffers=offload_buffers)

def load_lora_weights(self, pretrained_model_name_or_path_or_dict: Union[str, Dict[str, torch.Tensor]], **kwargs):
    # We could have accessed the unet config from `lora_state_dict()` too. We pass
    # it here explicitly to be able to tell that it's coming from an SDXL
    # pipeline.

    # Remove any existing hooks.
    if is_accelerate_available() and is_accelerate_version(">=", "0.17.0.dev0"):
        from accelerate.hooks import AlignDevicesHook, CpuOffload, remove_hook_from_module
    else:
        raise ImportError("Offloading requires `accelerate v0.17.0` or higher.")

    is_model_cpu_offload = False
    is_sequential_cpu_offload = False
    recursive = False
    for _, component in self.components.items():
        if isinstance(component, torch.nn.Module):
            if hasattr(component, "_hf_hook"):
                is_model_cpu_offload = isinstance(getattr(component, "_hf_hook"), CpuOffload)
                is_sequential_cpu_offload = isinstance(getattr(component, "_hf_hook"), AlignDevicesHook)
                logger.info(
                    "Accelerate hooks detected. Since you have called `load_lora_weights()`, the previous hooks will be first removed. Then the LoRA parameters will be loaded and the hooks will be applied again."
                )
                recursive = is_sequential_cpu_offload
                remove_hook_from_module(component, recurse=recursive)
    state_dict, network_alphas = self.lora_state_dict(
        pretrained_model_name_or_path_or_dict,
        unet_config=self.unet.config,
        **kwargs,
    )
    self.load_lora_into_unet(state_dict, network_alphas=network_alphas, unet=self.unet)

    text_encoder_state_dict = {k: v for k, v in state_dict.items() if "text_encoder." in k}
    if len(text_encoder_state_dict) > 0:
        self.load_lora_into_text_encoder(
            text_encoder_state_dict,
            network_alphas=network_alphas,
            text_encoder=self.text_encoder,
            prefix="text_encoder",
            lora_scale=self.lora_scale,
        )

    text_encoder_2_state_dict = {k: v for k, v in state_dict.items() if "text_encoder_2." in k}
    if len(text_encoder_2_state_dict) > 0:
        self.load_lora_into_text_encoder(
            text_encoder_2_state_dict,
            network_alphas=network_alphas,
            text_encoder=self.text_encoder_2,
            prefix="text_encoder_2",
            lora_scale=self.lora_scale,
        )

    # Offload back.
    if is_model_cpu_offload:
        self.enable_model_cpu_offload()
    elif is_sequential_cpu_offload:
        self.enable_sequential_cpu_offload()

