    if self.cur_att_layer >= 0 and is_cross:
        if attn.shape[1] == np.prod(self.attn_res):
            self.step_store[place_in_unet].append(attn)

    self.cur_att_layer += 1
    if self.cur_att_layer == self.num_att_layers:
        self.cur_att_layer = 0
        self.between_steps()

